// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function testFuzz_property(uint256 sent, address actor) public {
        // Keep the domain wide but admissible: msg.sender must be a real person,
        // the contract must be open, the wager limit is 1 ether, and sent must fit.
        vm.assume(actor != address(0));
        sent = bound(sent, 0, 1 ether);

        c.OpenToThePublic();
        vm.deal(actor, sent);
        vm.prank(actor, actor); // tx.origin == msg.sender == actor so onlyRealPeople passes
        (bool ok,) = address(c).call{value: sent}(abi.encodeWithSignature("wager()"));

        bool recorded = c.hasPlayerWagered(actor);

        if (sent == 1 ether) {
            // Reference accepts this, mutant rejects it. General rule: success iff the
            // sent value equals the wager limit.
            assertTrue(ok && recorded, "wager equality accepted in reference");
        } else {
            // Reference rejects these, mutant accepts them. General rule: rejection
            // iff the sent value differs from the wager limit.
            assertTrue(!ok && !recorded, "wager inequality rejected in reference");
        }
    }
}
